PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS Users (Id INTEGER PRIMARY KEY AUTOINCREMENT, Login TEXT UNIQUE NOT NULL, PasswordHash TEXT, Role TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS ProgrammingTasks (Id INTEGER PRIMARY KEY AUTOINCREMENT, Title TEXT NOT NULL, Statement TEXT NOT NULL, SolutionIdea TEXT NOT NULL, PolygonUrl TEXT, PreparedForCodeforces INTEGER NOT NULL DEFAULT 0, PreparedForYandexContest INTEGER NOT NULL DEFAULT 0, Difficulty INTEGER NOT NULL CHECK (Difficulty BETWEEN 1 AND 10), Note TEXT);
CREATE TABLE IF NOT EXISTS Tags (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS Contests (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT UNIQUE NOT NULL, Year INTEGER NOT NULL DEFAULT 2024);
CREATE TABLE IF NOT EXISTS TaskTags (TaskId INTEGER NOT NULL, TagId INTEGER NOT NULL, PRIMARY KEY (TaskId, TagId));
CREATE TABLE IF NOT EXISTS TaskContests (TaskId INTEGER NOT NULL, ContestId INTEGER NOT NULL, PRIMARY KEY (TaskId, ContestId));
-- Пользователи и демонстрационные записи добавляются приложением при первом запуске.
